from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib
out=ROOT/'reports/brownfields';out.mkdir(parents=True,exist_ok=True)
source=(ROOT/'assets/game.js').read_text()
probe="""window.__brown={g:()=>G,quote:brownfieldQuote,assess:brownfieldAssess,acquire:brownfieldAcquire,fund:brownfieldFund,reuse:brownfieldReuse,day:brownfieldDay,place:canPlace,money:totalMoney,owner:id=>{window.__brownWallet=urbanTitleAccount(readBuild(id));window.__brownRegionalOwner=!window.__brownWallet;if(!window.__brownWallet)window.__brownWallet={get cash(){return G.region;}};return window.__brownWallet.cash;},select:id=>{selected={id};openPanel('inspect');},close:()=>{const f=G.firms.find(f=>f.kind==='quarry'&&!f.closed);if(!f)throw Error('No quarry');liquidateFirm(f,'Controlled industrial closure');return f.building;}};"""
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':1280,'height':850});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();p.evaluate("__townTest.reset('regional',42)");assert p.evaluate('__townTest.load(__townTest.save())')
 id=p.evaluate('__brown.close()');q=p.evaluate('id=>__brown.quote(id)',id);assert q['ok'],q
 p.locator('[data-panel=construction]').click();p.locator('#brownfieldOffice>summary').click();before=p.evaluate('JSON.stringify({cash:__brown.g().treasury,total:__brown.money(),sites:__brown.g().brownfields,buildings:__brown.g().buildings})');p.locator(f'[data-brownfield-action=assess][data-brownfield-id="{id}"]').click();p.locator('[data-event-choice="1"]').click();assert p.evaluate('JSON.stringify({cash:__brown.g().treasury,total:__brown.money(),sites:__brown.g().brownfields,buildings:__brown.g().buildings})')==before
 p.locator(f'[data-brownfield-action=assess][data-brownfield-id="{id}"]').click();p.locator('[data-event-choice="0"]').click()
 state=p.evaluate('''id=>{const g=__brown.g(),s=g.brownfields[0],total=__brown.money(),cash=g.treasury;g.region+=cash;g.treasury=0;const fail=__brown.acquire(id);g.region-=cash;g.treasury=cash;if(fail.ok||Math.abs(__brown.money()-total)>.001)throw Error('Unfunded acquisition');return {assessment:s.assessment,ownerBefore:g.buildings.find(b=>b.id===id).owner};}''',id)
 owner_before=p.evaluate('id=>__brown.owner(id)',id)
 p.locator('#brownfieldOffice>summary').click();p.locator(f'[data-brownfield-action=acquire][data-brownfield-id="{id}"]').click();p.locator('[data-event-choice="0"]').click()
 owner_paid=p.evaluate('window.__brownWallet.cash')-owner_before;assert abs(owner_paid-(q['clearance'] if p.evaluate('window.__brownRegionalOwner') else q['clearance']-1500-350*len(q['tiles'])))<.01
 assert p.evaluate('''()=>{const s=__brown.g().brownfields[0];return !__brown.place(s.x,s.y,true,'home')&&!__brown.reuse(s.id,'home').ok&&__townTest.load(__townTest.save());}''')
 # Archive load may retain the open tab; re-open using real navigation.
 p.locator('[data-panel=community]').click();p.locator('[data-panel=construction]').click();p.locator('#brownfieldOffice>summary').click();p.locator(f'[data-brownfield-action=fund][data-brownfield-id="{id}"]').click();p.locator('[data-event-choice="0"]').click()
 result=p.evaluate('''()=>{const g=__brown.g(),s=g.brownfields[0],total=__brown.money(),remaining=s.remaining,old=g.policy.imports;g.policy.imports=false;__townTest.step(2);if(s.remaining!==remaining)throw Error('Closed trade completed works');g.policy.imports=old;for(let n=0;n<100&&s.status!=='ready';n++)__townTest.step(1);if(s.status!=='ready')throw Error('Never ready');if(Math.abs(__brown.money()-total)>.05)throw Error('Cash conservation');const saved=__townTest.save(),bad=JSON.parse(saved);bad.brownfields[0].remediation=-1;if(__townTest.load(bad)||__townTest.save()!==saved)throw Error('Invalid archive non-atomic');if(!__townTest.load(saved))throw Error('Ready restore');window.__brownReady=__townTest.save();return {day:__brown.g().day,remaining:__brown.g().brownfields[0].remaining,moneyError:__brown.money()-total,site:__brown.g().brownfields[0],valid:__townTest.validate()};}''');assert result['valid']['ok'],result
 p.locator('[data-panel=community]').click();p.locator('[data-panel=construction]').click();p.locator('#brownfieldOffice>summary').click();p.locator(f'[data-brownfield-action=park][data-brownfield-id="{id}"]').click();p.locator('[data-event-choice="0"]').click();assert p.evaluate("__brown.g().brownfields[0].status==='reused'&&__townTest.load(__townTest.save())")
 park=p.evaluate('__townTest.save()');result['reuseArms']=['park']
 for kind in ['home','grocer']:
  assert p.evaluate('__townTest.load(window.__brownReady)');total=p.evaluate('__brown.money()');p.locator('[data-panel=community]').click();p.locator('[data-panel=construction]').click();p.locator('#brownfieldOffice>summary').click();p.locator(f'[data-brownfield-action={kind}][data-brownfield-id="{id}"]').click();p.locator('[data-event-choice="0"]').click();assert p.evaluate('k=>__brown.g().brownfields[0].newKind===k',kind);assert abs(p.evaluate('__brown.money()')-total)<.05;assert p.evaluate('__townTest.load(__townTest.save())');result['reuseArms'].append(kind)
 assert p.evaluate('s=>__townTest.load(s)',park)
 p.locator('[data-panel=community]').click();p.locator('[data-panel=construction]').click();p.locator('#brownfieldOffice>summary').click();p.locator('#brownfieldOffice section').last.scroll_into_view_if_needed();p.screenshot(path=str(out/'renewed-site.png'));assert not errors,errors
 result.update({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'actualControls':True,'cancelNoMutation':True,'insufficientCash':True,'recipientCredited':owner_paid,'regionalTitleFallback':p.evaluate('window.__brownRegionalOwner'),'errors':errors});(out/'results.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2));b.close()
